function normalizar(s) {
  return (s || "")
    .toString()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
}

function paraIso(data) {
  const d = new Date(data);
  return isNaN(d.getTime()) ? null : d.toISOString();
}

function contemPalavra(texto, palavra) {
  return new RegExp("\\b" + palavra + "\\b").test(texto);
}

// só interessa política, desenvolvimento econômico/infraestrutura e tecnologia —
// descarta polícia/crime, clima, trânsito comum, entretenimento etc.
// Casamento cidade↔matéria e checagem de palavra-chave usam só o TÍTULO
// (o contentSnippet do G1 costuma trazer blocos de "leia também"/referência
// a outras cidades da região que geravam falso-positivo). O nome da cidade
// já casada é removido do título antes de checar a palavra-chave, pra cidade
// como "Governador Valadares" não colidir com a palavra-chave "governador".
const PALAVRAS_RELEVANTES = [
  // política
  "prefeitura", "prefeito", "prefeita", "vereador", "camara municipal",
  "eleicao", "eleicoes", "eleitoral", "candidato", "candidata", "deputado",
  "deputada", "senador", "senadora", "partido", "governo", "governador",
  "governadora", "assembleia legislativa", "congresso nacional",
  "emenda parlamentar", "secretaria de estado", "ministerio", "politica",
  "audiencia publica", "projeto de lei", "gestao municipal", "orcamento municipal",
  // desenvolvimento econômico / infraestrutura
  "investimento", "investe", "obra", "obras", "infraestrutura", "emprego",
  "empregos", "industria", "fabrica", "exportacao", "importacao", "pib",
  "economia", "economico", "desenvolvimento", "empresarial", "licitacao",
  "rodovia", "pavimentacao", "asfaltamento", "duplicacao", "incentivo fiscal",
  "porto seco", "distrito industrial", "parque industrial", "agronegocio",
  "comercio exterior", "turismo", "hidreletrica", "usina", "energia solar",
  "energia renovavel", "ferrovia", "aeroporto", "saneamento", "financiamento",
  "credito rural", "fomento", "arrecadacao", "receita municipal",
  "concurso publico", "geracao de renda", "cooperativa",
  // tecnologia
  "tecnologia", "startup", "inovacao", "digital", "inteligencia artificial",
  "aplicativo", "software", "internet", "5g", "ciberseguranca", "fibra optica",
  "data center", "automacao", "robotica", "e-commerce", "fintech",
  "smart city", "cidade inteligente",
];

function relevante(texto) {
  return PALAVRAS_RELEVANTES.some(p => contemPalavra(texto, p));
}

const municipios = $('Listar municípios').all().map(item => item.json);
const itensRss = $input.all().map(item => item.json);

const resultado = [];
const vistos = new Set();

for (const item of itensRss) {
  const titulo = item.title || "";
  const link = item.link || item.guid || "";
  if (!link) continue;

  const tituloNormalizado = normalizar(titulo);

  for (const m of municipios) {
    const nomeNormalizado = normalizar(m.name);
    // nomes com <= 4 letras geram falso-positivo fácil demais (evita casar por substring curta)
    if (nomeNormalizado.length <= 4) continue;
    if (!tituloNormalizado.includes(nomeNormalizado)) continue;

    const tituloSemCidade = tituloNormalizado.split(nomeNormalizado).join(" ");
    if (!relevante(tituloSemCidade)) continue;

    const chave = `${m.id}-${link}`;
    if (vistos.has(chave)) continue;
    vistos.add(chave);

    resultado.push({
      json: {
        municipio_id: m.id,
        source: "G1",
        headline: titulo.slice(0, 500),
        url: link,
        published_at: paraIso(item.pubDate || item.isoDate),
      }
    });
  }
}

return resultado;
